package com.stacklab.controller;
import com.stacklab.dto.ApiDtos.NotificationView;import com.stacklab.entity.*;import com.stacklab.exception.*;import com.stacklab.repository.NotificationRepository;import com.stacklab.service.CurrentUserService;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import org.springframework.security.access.AccessDeniedException;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@RestController @RequestMapping("/api/notifications") @SecurityRequirement(name="bearerAuth") public class NotificationController{private final NotificationRepository notifications;private final CurrentUserService current;public NotificationController(NotificationRepository n,CurrentUserService c){notifications=n;current=c;}@GetMapping public List<NotificationView> list(){return notifications.findByUserIdOrderByCreatedAtDesc(current.get().getId()).stream().map(NotificationView::of).toList();}@PatchMapping("/{id}/read")@Transactional public NotificationView read(@PathVariable Long id){Notification n=notifications.findById(id).orElseThrow(()->new NotFoundException("Notification not found"));if(!n.getUser().getId().equals(current.get().getId()))throw new AccessDeniedException("Notification belongs to another user");n.markRead();return NotificationView.of(n);}}
